import{_ as i,o as t,c as e,ag as s}from"./chunks/framework.WmBmIPw-.js";const o="/Personal/assets/slide-01.D4KEk0NG.png",r="/Personal/assets/slide-02.EKJbu_V2.png",l="/Personal/assets/slide-03.BdOTnYxi.png",p="/Personal/assets/slide-04.COuksAHQ.png",n="/Personal/assets/slide-05.CBfyyUgZ.png",h="/Personal/assets/slide-06.DB0IsqRB.png",d="/Personal/assets/slide-07.CiKwWGn5.png",c="/Personal/assets/slide-08.D7Ibm_lU.png",g="/Personal/assets/slide-09.Bjtd3kk0.png",f="/Personal/assets/slide-10.B17A1mtW.png",m="/Personal/assets/slide-11.QVv7ivBR.png",_="/Personal/assets/slide-12.9qyb1NPY.png",b="/Personal/assets/slide-13.C0_YAhpN.png",N=JSON.parse('{"title":"第 1 课 · 基本概念","description":"","frontmatter":{},"headers":[],"relativePath":"reinforcement-learning/basic-concepts.md","filePath":"reinforcement-learning/basic-concepts.md","lastUpdated":1794320867000}'),P={name:"reinforcement-learning/basic-concepts.md"};function u(w,a,y,q,B,T){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="第-1-课-·-基本概念" tabindex="-1">第 1 课 · 基本概念 <a class="header-anchor" href="#第-1-课-·-基本概念" aria-label="Permalink to &quot;第 1 课 · 基本概念&quot;">​</a></h1><p>赵世钰（西湖大学）《强化学习的数学原理》第 1 课上半段，时长 18 分 48 秒。以下按 PPT 换页顺序整理，共 13 页（含封面）。每页的画面保留课上标注，下方讲解根据视频原声整理。</p><p><a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2" target="_blank" rel="noreferrer">B 站原视频（第 2 个分 P）</a></p><h2 id="_01-·-第-1-课封面" tabindex="-1">01 · 第 1 课封面 <a class="header-anchor" href="#_01-·-第-1-课封面" aria-label="Permalink to &quot;01 · 第 1 课封面&quot;">​</a></h2><figure><img src="'+o+'" alt="第 1 课封面的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>PPT 封面 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=4">00:04–00:21 回看</a></figcaption></figure><p>赵世钰老师介绍本讲的主题：强化学习的基本概念。这些术语会在后续课程反复出现，后面的公式和算法都会用到这套语言。</p><h2 id="_02-·-本讲怎么展开" tabindex="-1">02 · 本讲怎么展开 <a class="header-anchor" href="#_02-·-本讲怎么展开" aria-label="Permalink to &quot;02 · 本讲怎么展开&quot;">​</a></h2><figure><img src="'+r+'" alt="本讲怎么展开的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 1/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=21">00:21–00:39 回看</a></figcaption></figure><p>课程分两步。先用一个具体例子认识强化学习的概念，再放到马尔可夫决策过程的框架里给出正式描述。当前这一段从网格世界入手，依次讲状态、动作、状态转移和策略。</p><h2 id="_03-·-贯穿课程的网格世界" tabindex="-1">03 · 贯穿课程的网格世界 <a class="header-anchor" href="#_03-·-贯穿课程的网格世界" aria-label="Permalink to &quot;03 · 贯穿课程的网格世界&quot;">​</a></h2><figure><img src="'+l+'" alt="贯穿课程的网格世界的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 2/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=38">00:39–02:49 回看</a></figcaption></figure><p>把机器人放进一个 3×3 的网格中。白格可以通行，黄格标为禁区，蓝格是目标，外框是边界。机器人可以沿上下左右方向在相邻格子间移动。任务是从任意给定起点找到一条到目标的好路线。</p><p>怎么判断一条路线好不好？老师画出反复折返和试图越界的走法，并指出应尽量避开禁区。这里先建立直觉，最优路径和最优策略的正式定义留到后面。</p><h2 id="_04-·-状态与状态空间" tabindex="-1">04 · 状态与状态空间 <a class="header-anchor" href="#_04-·-状态与状态空间" aria-label="Permalink to &quot;04 · 状态与状态空间&quot;">​</a></h2><figure><img src="'+p+'" alt="状态与状态空间的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 3/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=169">02:49–04:41 回看</a></figcaption></figure><p>状态描述智能体相对于环境所处的情形。在这个例子里，只用机器人所在的格子就能表示状态。九个格子依次编号为 s₁ 到 s₉，目标格和示例中的禁区也在编号中。</p><p>格子编号是索引，对应二维坐标 (x, y)。更复杂的机器人问题还可能把速度、加速度等信息放进状态。所有可能的状态组成集合 𝒮，这个集合叫状态空间。</p><h2 id="_05-·-动作与动作空间" tabindex="-1">05 · 动作与动作空间 <a class="header-anchor" href="#_05-·-动作与动作空间" aria-label="Permalink to &quot;05 · 动作与动作空间&quot;">​</a></h2><figure><img src="'+n+'" alt="动作与动作空间的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 4/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=280">04:41–05:45 回看</a></figcaption></figure><p>这个网格为每个状态列出五个动作。a₁ 向上，a₂ 向右，a₃ 向下，a₄ 向左，a₅ 原地不动。𝒜(sᵢ) 表示在状态 sᵢ 可选择的所有动作。</p><p>课上特意问不同状态的动作集合能否不同。可以按环境需要分别定义。本例给每个状态同一套指令，至于发出指令后能否移动，则由下一页的状态转移决定。</p><h2 id="_06-·-状态转移-发出动作之后" tabindex="-1">06 · 状态转移：发出动作之后 <a class="header-anchor" href="#_06-·-状态转移-发出动作之后" aria-label="Permalink to &quot;06 · 状态转移：发出动作之后&quot;">​</a></h2><figure><img src="'+h+'" alt="状态转移：发出动作之后的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 5/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=344">05:45–08:03 回看</a></figcaption></figure><p>智能体执行动作后，环境给出下一状态。在左上角 s₁ 选择向右的 a₂，会到 s₂。若在同一格选择向上的 a₁，外框挡住移动，结果仍是 s₁。</p><p>老师补充，游戏可以把撞墙后的结果另设为弹到 s₄ 或 s₇。现实机器人能到哪里受物理条件限制。状态转移规则表达的正是智能体与环境怎样交互。</p><h2 id="_07-·-状态转移-如何定义禁区" tabindex="-1">07 · 状态转移：如何定义禁区 <a class="header-anchor" href="#_07-·-状态转移-如何定义禁区" aria-label="Permalink to &quot;07 · 状态转移：如何定义禁区&quot;">​</a></h2><figure><img src="'+d+'" alt="状态转移：如何定义禁区的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 6/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=482">08:03–09:47 回看</a></figcaption></figure><p>从中间格 s₅ 向右走会遇到黄色的 s₆。老师给出两种建模方法。如果允许进入禁区但要受惩罚，下一状态是 s₆。如果禁区像被墙围住一样不可进入，向右之后仍在 s₅。</p><p>课程采用第一种设定。老师指出，把这些格子排除在搜索之外会缩小可达范围。允许进入时，智能体还得在绕远和接受惩罚之间权衡，甚至可能穿过禁区走近路。</p><h2 id="_08-·-状态转移-用表格查下一状态" tabindex="-1">08 · 状态转移：用表格查下一状态 <a class="header-anchor" href="#_08-·-状态转移-用表格查下一状态" aria-label="Permalink to &quot;08 · 状态转移：用表格查下一状态&quot;">​</a></h2><figure><img src="'+c+'" alt="状态转移：用表格查下一状态的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 7/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=587">09:47–10:43 回看</a></figcaption></figure><p>状态转移表以当前状态为行，以动作为列，交叉格里填下一状态。比如在 s₁ 向上查得 s₁，在 s₆ 向下查得 s₉，向左查得 s₅。</p><p>这张表的每个格只写一个结果，因此适合确定性转移。如果把撞墙设计成可能留在 s₁，也可能弹到 s₄ 或 s₇，就需要一种能表示多个结果的写法。</p><h2 id="_09-·-状态转移概率" tabindex="-1">09 · 状态转移概率 <a class="header-anchor" href="#_09-·-状态转移概率" aria-label="Permalink to &quot;09 · 状态转移概率&quot;">​</a></h2><figure><img src="'+g+'" alt="状态转移概率的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 8/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=643">10:43–12:50 回看</a></figcaption></figure><p>p(s′｜s,a) 表示已经处于 s 并执行 a 的条件下，下一状态为 s′ 的概率。例如确定性网格中，从 s₁ 向右到 s₂ 的概率是 1，其他下一状态的概率是 0。</p><p>老师用风扰动举例说明随机转移。即使发出的动作相同，结果也可能不一样。手写例子把到 s₂ 和到 s₅ 的概率各设为 0.5。这里随机的是动作执行后的落点。</p><h2 id="_10-·-策略-看每格的箭头" tabindex="-1">10 · 策略：看每格的箭头 <a class="header-anchor" href="#_10-·-策略-看每格的箭头" aria-label="Permalink to &quot;10 · 策略：看每格的箭头&quot;">​</a></h2><figure><img src="'+f+'" alt="策略：看每格的箭头的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 9/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=770">12:50–14:35 回看</a></figcaption></figure><p>策略告诉智能体在某个状态该选什么动作。图里的绿色箭头给出了每个格子的指令，目标格里的圆圈表示原地不动。</p><p>老师沿箭头演示了从 s₁ 出发的路线：先向右到 s₂，再一路向下到 s₈，最后向右到 s₉。换成 s₃ 或 s₇ 出发，会得到另一条路径。每一步都先由策略选动作，再由状态转移决定落点。</p><h2 id="_11-·-确定性策略的概率写法" tabindex="-1">11 · 确定性策略的概率写法 <a class="header-anchor" href="#_11-·-确定性策略的概率写法" aria-label="Permalink to &quot;11 · 确定性策略的概率写法&quot;">​</a></h2><figure><img src="'+m+'" alt="确定性策略的概率写法的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 10/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=875">14:35–16:04 回看</a></figcaption></figure><p>用 π(a｜s) 写在状态 s 选择动作 a 的概率。对图中的 s₁，向右的 a₂ 概率为 1，其他四个动作概率为 0。对固定状态，所有动作的概率加起来等于 1。</p><p>如果每个状态都把全部概率给某一个动作，就是确定性策略。这里的条件只有当前状态，概率描述的是动作选择。</p><h2 id="_12-·-随机策略" tabindex="-1">12 · 随机策略 <a class="header-anchor" href="#_12-·-随机策略" aria-label="Permalink to &quot;12 · 随机策略&quot;">​</a></h2><figure><img src="'+_+'" alt="随机策略的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 11/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=964">16:04–17:04 回看</a></figcaption></figure><p>随机策略可以在同一状态为多个动作分配正概率。老师把 s₁ 的策略改成向右和向下各 0.5，向上、向左和原地不动的概率都为 0。图中的虚线画出两种可能的走法。</p><p>随机策略改变的是智能体如何选择指令。在确定性环境里，随机选好一个动作后，下一格仍由该动作唯一确定。</p><h2 id="_13-·-策略表与按概率选动作" tabindex="-1">13 · 策略表与按概率选动作 <a class="header-anchor" href="#_13-·-策略表与按概率选动作" aria-label="Permalink to &quot;13 · 策略表与按概率选动作&quot;">​</a></h2><figure><img src="'+b+'" alt="策略表与按概率选动作的 PPT 画面" width="642" height="480" loading="lazy"><figcaption>课件页码 12/26 · <a href="https://www.bilibili.com/video/BV1sd4y167NS?p=2&amp;t=1023">17:04–18:48 回看</a></figcaption></figure><p>策略表也把状态排成行、动作排成列，但格子里写的是动作概率。s₁ 行中向右和向下两项各 0.5，s₅ 行中向下是 1。同一张表可以记录确定性选择和随机选择，编程时可用数组或矩阵存储。</p><p>老师用 0 到 1 的线段说明怎么执行策略。以 s₁ 为例，在 [0, 1) 内均匀抽一个数，落在前半段就选 a₂ 向右，落在后半段就选 a₃ 向下。两个区间各占一半，恰好得到表中的两个 0.5。</p>',53)])])}const x=i(P,[["render",u]]);export{N as __pageData,x as default};
